"""Record already performed actual image inspection; never renders/rebuilds art."""
from pathlib import Path
import json,hashlib,datetime
R=Path(__file__).resolve().parents[1]
def load(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def record(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2),encoding='utf-8')
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
ap=R/'assets/world/infrastructure/airports/manifest.json';am=load(ap);adir=R/'previews/world/airports'
names=['all-layouts.jpg','tiles-1.jpg','tiles-2.jpg','tiles-3.jpg','tiles-4.jpg','airport-radar-scan-phases.jpg','airport-windsock-flutter-phases.jpg']
airport={'schema':'actual-art-visual-review.v1','recordedAt':now,'inspector':'airport_final production agent; independent whole-pack review separate','inspectionContext':'Actual view_image inspection performed during completed airport production, carried forward after current source/preview hashes verified; no re-render or claim of new image generation.','manifest':ap.relative_to(R).as_posix(),'manifestSHA256':sha(ap),'result':'local-static-and-motion-art-checked-user-acceptance-pending','coverage':{'sourceAirportTypes':10,'sourceTileIds':74,'sourceLayoutPlacements':265,'animationFrames':20},'pages':[{'file':(adir/n).relative_to(R).as_posix(),'sha256':sha(adir/n),'result':'reviewed actual pixels; legible ground lanes, complete footprint, separate modules, consistent support placement'}for n in names],'layoutPNGs':[{'file':s['preview']['file'],'sha256':sha(R/s['preview']['file']),'matchesAcceptedPreviewHash':sha(R/s['preview']['file'])==s['preview']['sha256']}for s in am['sourceLayouts']],'findings':['Double fence sides retain both source edges; apron line does not include unrelated runway border.','Radio mast uses actual radio-mast art, distinct from ATC tower.','Radar and windsock supports stay fixed; movement is declared geometric part animation, not newly generated frames.'],'limitations':['User art approval pending.','All world/body detail is native-source crop or declared derivative, never inferred from output canvas.','Taxi vehicle routing, sprite order and Unity placement not run.','Oilrig preview surrounding water is context; retain its actual source airport footprint.'],'unityValidated':False,'userAccepted':False}
assert all(x['matchesAcceptedPreviewHash']for x in airport['layoutPNGs'])
record(R/'records/world-production/airport-visual-review.json',airport)
aq=R/'records/world-production/airport-validation.json';a=load(aq);a['visualReview']={'record':'records/world-production/airport-visual-review.json','result':airport['result'],'currentPreviewHashesVerified':True};record(aq,a)
lp=R/'records/world-production/transport-lane-validation.json';l=load(lp);mp=R/'assets/world/infrastructure/transport-runtime/manifest.json';pages=l['pages']
lane={'schema':'actual-art-visual-review.v1','recordedAt':now,'inspector':'airport_final production agent; independent whole-pack review separate','manifest':mp.relative_to(R).as_posix(),'manifestSHA256':sha(mp),'result':'local-static-lane-assembly-checked-user-acceptance-pending','coverage':{'tunnelStates':72,'bridgeTypes':13,'bridgeAxisDeckStates':52,'bridgeRoleMappings':364,'uniqueFlatPositiveNegativeSlopeImages':156,'materialUVStrips':5},'pages':[{'file':p['image'],'sha256':sha(R/p['image']),'matchesFinalContactHash':sha(R/p['image'])==p['sha256'],'result':'actually viewed final contact/detail pixels; passed static art checks'}for p in pages],'additionalJoinReview':{'file':'previews/world/transport-lanes/lane-joins-native.jpg','sha256':sha(R/'previews/world/transport-lanes/lane-joins-native.jpg'),'result':'actual1:1 road and rail three-module joins inspected; no full grass tiles or floating floor slabs'},'findings':['Initial prototype over-cleared native black portal floor beyond the sampled lane and left a transparent wedge. Restricted Alpha ownership to the actual lane common interior; final SE/SW mouths retain native dark floor outside the lane with continuous central approach.','Clipped the road UV interior and removed a few remaining native green edge pixels by Alpha; actual pavement/marking colour remains source paint.','Actual jade trusses and tubular roofs remain foreground; lane cannot cover these painted structures. All outside-ownership native structure RGBA remains exact.','Back-facing tunnel NE/NW correctly has no foreground road layer.','Whole and separate layers are alternatives; verified each final layered composition byte-identical to its whole PNG.'],'mechanicalValidation':{'file':lp.relative_to(R).as_posix(),'checks':l['checks'],'failures':len(l['failures'])},'browserValidation':'records/world-production/transport-lane-browser-validation.json','joinGeometry':'records/world-production/bridge-joins-geometry.json','limitations':['Only existing painted source pixels, UV projection, clipping and colour grades; no new AI image.','Climate slots are declared colour grades, not new snow/desert original painting.','Current bridge front layer protects all non-floor native structure; actual vehicle rear/foreground splitting, clearance and Unity render ordering remain integration checks.','User image acceptance remains pending.'],'unityValidated':False,'userAccepted':False}
assert all(p['matchesFinalContactHash']for p in lane['pages'])
record(R/'records/world-production/transport-lane-visual-review.json',lane)
l['visualReview']={'record':'records/world-production/transport-lane-visual-review.json','result':lane['result'],'all17PreviewPagesActuallyViewed':True,'additionalNativeSizeJoinsViewed':True};record(lp,l)
rp=R/'records/world-production/transport-runtime-validation.json';rt=load(rp);rt['visualReview']=l['visualReview'];record(rp,rt)
print(json.dumps({'airportVisualPages':len(airport['pages']),'airportLayoutsCurrentHashes':len(airport['layoutPNGs']),'laneVisualPages':len(lane['pages']),'laneFormalManifestSHA256':lane['manifestSHA256']},ensure_ascii=False))
